<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php'; require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Bursar'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired.');}
$line=filter_var($_POST['line_id']??null,FILTER_VALIDATE_INT);$type=(string)($_POST['item_type']??'');$desc=trim((string)($_POST['description']??''));$amount=$_POST['amount']??null;$delete=filter_var($_POST['delete_item_id']??null,FILTER_VALIDATE_INT);$run=filter_var($_POST['run_id']??null,FILTER_VALIDATE_INT);
if(!$line||!$run||($delete===false)||(!$delete&&(!in_array($type,['Earning','Deduction'],true)||$desc===''||strlen($desc)>120||!is_numeric($amount)||(float)$amount<=0||(float)$amount>9999999999.99))){$_SESSION['error']='Check the payroll item details.';header('Location: ../?page=payroll&run='.(int)$run);exit;}
$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT l.id,r.id run_id FROM payroll_lines l JOIN payroll_runs r ON r.id=l.run_id WHERE l.id=:line AND r.id=:run AND r.status='Draft' FOR UPDATE");$q->execute(['line'=>$line,'run'=>$run]);if(!$q->fetch())throw new DomainException('Payroll items can only be changed in a draft run.');if($delete){$q=$pdo->prepare('DELETE FROM payroll_line_items WHERE id=:id AND payroll_line_id=:line');$q->execute(['id'=>$delete,'line'=>$line]);if(!$q->rowCount())throw new DomainException('This payroll item is no longer available.');audit_log('payroll.item_removed','payroll_line_items',$delete,['line_id'=>$line]);}else{$q=$pdo->prepare('INSERT INTO payroll_line_items(payroll_line_id,item_type,description,amount,created_by) VALUES(:line,:type,:description,:amount,:user)');$q->execute(['line'=>$line,'type'=>$type,'description'=>$desc,'amount'=>number_format((float)$amount,2,'.',''),'user'=>$user['id']]);audit_log('payroll.item_added','payroll_line_items',(int)$pdo->lastInsertId(),['line_id'=>$line,'type'=>$type,'amount'=>(float)$amount]);}$pdo->commit();$_SESSION['notice']='Draft payroll item saved.';}catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();error_log('Payroll item save failed: '.$x->getMessage());$_SESSION['error']=$x instanceof DomainException?$x->getMessage():'Could not save the payroll item.';}header('Location: ../?page=payroll&run='.(int)$run);exit;
